import{R as e,S as t,w as n}from"./index-CeCVboEw.js";var r={class:`max-w-4xl mx-auto p-8 bg-white shadow rounded-lg`},i={__name:`PrivacyPolicy`,setup(i){return(i,a)=>(e(),t(`div`,r,[...a[0]||=[n(`<h1 class="text-3xl font-bold mb-6">Политика конфиденциальности</h1><section class="mb-6"><h2 class="text-2xl font-semibold mb-2 text-left">1. Общие положения</h2><p class="text-gray-700"> Настоящая Политика конфиденциальности описывает, как мы собираем, используем, обрабатываем и защищаем персональные данные пользователей при работе с нашим сайтом и сервисами. </p></section><section class="mb-6"><h2 class="text-2xl font-semibold mb-2 text-left">2. Сбор информации</h2><p class="text-gray-700"> Мы можем собирать следующую информацию: </p><ul class="list-disc pl-6 text-gray-700 space-y-1"><li>ФИО и контактные данные (email, телефон);</li><li>Данные учетной записи при регистрации;</li><li>Информацию об использовании сайта (логи, IP-адрес, cookies).</li></ul></section><section class="mb-6"><h2 class="text-2xl font-semibold mb-2 text-left">3. Использование данных</h2><p class="text-gray-700">Собранные данные используются для:</p><ul class="list-disc pl-6 text-gray-700 space-y-1"><li>оказания и улучшения наших услуг;</li><li>персонализации интерфейса и контента;</li><li>обратной связи с пользователем;</li><li>соблюдения требований законодательства.</li></ul></section><section class="mb-6"><h2 class="text-2xl font-semibold mb-2 text-left">4. Передача данных третьим лицам</h2><p class="text-gray-700"> Мы не передаем персональные данные третьим лицам без согласия пользователя, за исключением случаев, предусмотренных законом или необходимых для оказания услуг (например, платежные системы). </p></section><section class="mb-6"><h2 class="text-2xl font-semibold mb-2 text-left">5. Хранение и защита данных</h2><p class="text-gray-700"> Мы применяем технические и организационные меры для защиты данных от несанкционированного доступа, изменения, раскрытия или уничтожения. </p></section><section class="mb-6"><h2 class="text-2xl font-semibold mb-2 text-left">6. Права пользователя</h2><p class="text-gray-700">Вы имеете право:</p><ul class="list-disc pl-6 text-gray-700 space-y-1"><li>запросить доступ к своим персональным данным;</li><li>вносить изменения или исправления;</li><li>требовать удаления данных;</li><li>отозвать согласие на обработку персональных данных.</li></ul></section><section class="mb-6"><h2 class="text-2xl font-semibold mb-2 text-left">7. Контакты</h2><p class="text-gray-700"> Если у вас возникли вопросы, свяжитесь с нами: <a href="mailto:privacy@example.com" class="text-blue-600 underline">privacy@example.com</a></p></section>`,8)]]))}};export{i as default};